    fn find_preset_by_spec<'a, T, IdOf, NameOf>(
        items: &'a [T],
        spec: &str,
        id_of: IdOf,
        name_of: NameOf,
    ) -> Option<&'a T>
    where
        IdOf: Fn(&T) -> u32,
        NameOf: Fn(&T) -> &str,
    {
        items
            .iter()
            .find(|item| id_of(item).to_string() == spec)
            .or_else(|| {
                items
                    .iter()
                    .find(|item| name_of(item).trim().eq_ignore_ascii_case(spec))
            })
    }
