    fn parse_svg_path(d: &str) -> Option<tiny_skia::Path> {
        let mut pb = tiny_skia::PathBuilder::new();
        let clean_d = d.replace(',', " ");
        let mut tokens = clean_d.split_whitespace().peekable();
        while let Some(token) = tokens.next() {
            match token {
                "M" | "m" => {
                    let x = tokens.next()?.parse::<f32>().ok()?;
                    let y = tokens.next()?.parse::<f32>().ok()?;
                    pb.move_to(x, y);
                }
                "L" | "l" => {
                    let x = tokens.next()?.parse::<f32>().ok()?;
                    let y = tokens.next()?.parse::<f32>().ok()?;
                    pb.line_to(x, y);
                }
                "C" | "c" => {
                    let x1 = tokens.next()?.parse::<f32>().ok()?;
                    let y1 = tokens.next()?.parse::<f32>().ok()?;
                    let x2 = tokens.next()?.parse::<f32>().ok()?;
                    let y2 = tokens.next()?.parse::<f32>().ok()?;
                    let x3 = tokens.next()?.parse::<f32>().ok()?;
                    let y3 = tokens.next()?.parse::<f32>().ok()?;
                    pb.cubic_to(x1, y1, x2, y2, x3, y3);
                }
                "Q" | "q" => {
                    let x1 = tokens.next()?.parse::<f32>().ok()?;
                    let y1 = tokens.next()?.parse::<f32>().ok()?;
                    let x2 = tokens.next()?.parse::<f32>().ok()?;
                    let y2 = tokens.next()?.parse::<f32>().ok()?;
                    pb.quad_to(x1, y1, x2, y2);
                }
                "Z" | "z" => {
                    pb.close();
                }
                _ => {}
            }
        }
        pb.finish()
    }

    fn parse_svg_path_warped<F>(d: &str, map: &F) -> Option<tiny_skia::Path>
    where
        F: Fn(f32, f32) -> (f32, f32),
    {
        let mut pb = tiny_skia::PathBuilder::new();
        let clean_d = d.replace(',', " ");
        let mut tokens = clean_d.split_whitespace().peekable();
        while let Some(token) = tokens.next() {
            match token {
                "M" | "m" => {
                    let x = tokens.next()?.parse::<f32>().ok()?;
                    let y = tokens.next()?.parse::<f32>().ok()?;
                    let (px, py) = map(x, y);
                    pb.move_to(px, py);
                }
                "L" | "l" => {
                    let x = tokens.next()?.parse::<f32>().ok()?;
                    let y = tokens.next()?.parse::<f32>().ok()?;
                    let (px, py) = map(x, y);
                    pb.line_to(px, py);
                }
                "C" | "c" => {
                    let x1 = tokens.next()?.parse::<f32>().ok()?;
                    let y1 = tokens.next()?.parse::<f32>().ok()?;
                    let x2 = tokens.next()?.parse::<f32>().ok()?;
                    let y2 = tokens.next()?.parse::<f32>().ok()?;
                    let x3 = tokens.next()?.parse::<f32>().ok()?;
                    let y3 = tokens.next()?.parse::<f32>().ok()?;
                    let (p1x, p1y) = map(x1, y1);
                    let (p2x, p2y) = map(x2, y2);
                    let (p3x, p3y) = map(x3, y3);
                    pb.cubic_to(p1x, p1y, p2x, p2y, p3x, p3y);
                }
                "Q" | "q" => {
                    let x1 = tokens.next()?.parse::<f32>().ok()?;
                    let y1 = tokens.next()?.parse::<f32>().ok()?;
                    let x2 = tokens.next()?.parse::<f32>().ok()?;
                    let y2 = tokens.next()?.parse::<f32>().ok()?;
                    let (p1x, p1y) = map(x1, y1);
                    let (p2x, p2y) = map(x2, y2);
                    pb.quad_to(p1x, p1y, p2x, p2y);
                }
                "Z" | "z" => {
                    pb.close();
                }
                _ => {}
            }
        }
        pb.finish()
    }

    pub fn add_active_step(preset_id: u32, step_index: usize) {
        let mut active = ACTIVE_MACRO_STEPS.lock();
        active.entry(preset_id).or_default().insert(step_index);
        drop(active);
        request_ui_repaint();
    }

    pub fn remove_active_step(preset_id: u32, step_index: usize) {
        let mut active = ACTIVE_MACRO_STEPS.lock();
        if let Some(set) = active.get_mut(&preset_id) {
            set.remove(&step_index);
            if set.is_empty() {
                active.remove(&preset_id);
            }
        }

        drop(active);
        request_ui_repaint();
    }

    pub struct ActiveStepGuard {
        preset_id: u32,
        step_index: usize,
    }

    impl ActiveStepGuard {
        pub fn new(preset_id: u32, step_index: usize) -> Self {
            add_active_step(preset_id, step_index);
            Self {
                preset_id,
                step_index,
            }
        }
    }

    impl Drop for ActiveStepGuard {
        fn drop(&mut self) {
            remove_active_step(self.preset_id, self.step_index);
        }
    }

    pub fn is_vision_following_active_by_spec(spec: &str) -> bool {
        if let Ok(preset) = vision_preset_by_id(spec) {
            HOOK_STATE
                .lock()
                .vision_following_presets
                .contains(&preset.id)
        } else {
            false
        }
    }

    pub fn is_timer_preset_active(t_id: Option<u32>) -> bool {
        if let Some(id) = t_id {
            HOOK_STATE
                .lock()
                .active_timers
                .get(&id)
                .map(|s| s.running)
                .unwrap_or(false)
        } else {
            false
        }
    }

    pub fn stop_timer_preset(t_id: Option<u32>) {
        let Some(id) = t_id else {
            return;
        };
        HOOK_STATE.lock().active_timers.remove(&id);
        wake_command_queue();
        request_ui_repaint();
    }

    static OVERLAY_COMMAND_TX: Lazy<Mutex<Option<Sender<OverlayCommand>>>> =
        Lazy::new(|| Mutex::new(None));
    static RANDOM_STATE: Lazy<std::sync::atomic::AtomicU64> = Lazy::new(|| {
        let seed = std::time::SystemTime::now()
            .duration_since(std::time::SystemTime::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos() as u64;
        std::sync::atomic::AtomicU64::new(seed ^ 0x9E37_79B9_7F4A_7C15)
    });
